[tikz]
\begin{tikzpicture}[scale=1]
\coordinate (B) at (0,0);
\coordinate (P) at (0,-2.2);
\coordinate (Q) at (2.2,0);
\draw[dashed] (P)--(B)--(Q);
\draw (P)--(Q) node[midway,above right] {$90\text{ m}$};
\coordinate (ra) at ($(B)!0.28cm!(P)$);
\coordinate (rb) at ($(B)!0.28cm!(Q)$);
\draw (ra)--($(ra)+(rb)-(B)$)--(rb);
\draw[-{Stealth}] (P)--($(P)+(0,1.0)$) node[above left] {N};
